import { Injectable } from '@angular/core';
import { meIcons, MeIcon, meIconSet, reportingGroupMeX20 } from '@monitel/me-icons';
import type {IconColorOptions} from './types';
const REG_EXP_FOR_ICON_PATH = new RegExp("^(/?([^/\0]+/)*[^/\0]+.(svg|jpeg|png|ico))$");
const DX_ICONS: string[] = ["add", "airplane", "bookmark", "box", "car", "card", "cart", "chart", "check", "clear", "clock", "close", "coffee", "comment", "doc", "file", "download", "dragvertical", "edit", "email", "event", "eventall", "favorites", "find", "filter", "folder", "activefolder", "food", "gift", "globe", "group", "help", "home", "image", "info", "key", "like", "map", "menu", "message", "money", "music", "overflow", "percent", "photo", "plus", "minus", "preferences", "product", "pulldown", "refresh", "remove", "revert", "runner", "save", "search", "tags", "tel", "tips", "todo", "toolbox", "trash", "user", "upload", "floppy", "arrowleft", "arrowdown", "arrowright", "arrowup", "spinleft", "spinprev", "spinright", "spinnext", "spindown", "spinup", "chevronleft", "chevronprev", "back", "chevronright", "chevronnext", "chevrondown", "chevronup", "chevrondoubleleft", "chevrondoubleright", "equal", "notequal", "less", "greater", "lessorequal", "greaterorequal", "isblank", "isnotblank", "sortup", "sortdown", "sortuptext", "sortdowntext", "sorted", "expand", "collapse", "columnfield", "rowfield", "datafield", "fields", "fieldchooser", "columnchooser", "pin", "unpin", "pinleft", "pinright", "contains", "startswith", "endswith", "doesnotcontain", "range", "export", "exportxlsx", "exportpdf", "exportselected", "ordersbox", "warning", "taskhelpneeded", "more", "square", "clearsquare", "repeat", "selectall", "unselectall", "print", "bold", "italic", "underline", "strike", "indent", "increaselinespacing", "font", "fontsize", "shrinkfont", "growfont", "color", "background", "fill", "palette", "superscript", "subscript", "header", "blockquote", "formula", "codeblock", "orderedlist", "bulletlist", "increaseindent", "decreaseindent", "decreaselinespacing", "alignleft", "alignright", "aligncenter", "alignjustify", "link", "video", "mention", "variable", "clearformat", "accountbox", "fullscreen", "hierarchy", "docfile", "docxfile", "pdffile", "pptfile", "pptxfile", "rtffile", "txtfile", "xlsfile", "xlsxfile", "copy", "cut", "paste", "share", "inactivefolder", "newfolder", "movetofolder", "parentfolder", "rename", "detailslayout", "contentlayout", "smalliconslayout", "mediumiconslayout", "undo", "redo", "hidepanel", "showpanel", "checklist", "verticalaligntop", "verticalaligncenter", "verticalalignbottom", "rowproperties", "columnproperties", "cellproperties", "tableproperties", "splitcells", "mergecells", "deleterow", "deletecolumn", "insertrowabove", "insertrowbelow", "insertcolumnleft", "insertcolumnright", "inserttable", "deletetable", "edittableheader", "addtableheader", "pasteplaintext", "importselected", "import", "textdocument", "jpgfile", "bmpfile", "svgfile", "attach", "return", "indeterminatestate", "lock", "unlock", "imgarlock", "imgarunlock", "bell", "sun", "arrowback", "taskcomplete", "taskrejected", "taskinprogress", "taskstop", "clearcircle", "send", "pinmap", "photooutline", "panelright", "panelleft", "optionsgear", "moon", "login", "eyeopen", "eyeclose", "expandform", "description", "belloutline", "to", "errorcircle", "datatrending", "dataarea", "datausage", "datapie", "handlevertical", "handlehorizontal", "triangleup", "triangledown", "triangleright", "triangleleft", "sendfilled", "chat", "fixcolumn", "unfixcolumn", "fixcolumnleft", "stickcolumn", "fixcolumnright"];

@Injectable({
  providedIn: 'root',
})
export class MeIconsRegistry {
  private registry = new Map<meIcons, string>();
  private parser = new DOMParser();
  private serializer = new XMLSerializer();

  public registerIcons(icons: MeIcon[]): void {
    icons.forEach((icon: any) => this.registry.set(icon.name, icon.data));
  }
  private meIconNameSet = meIconSet.map((item) => item.name);

  public getIconFromString(
    iconName: meIcons | string,
    color?: string | IconColorOptions[],
    selector? : string,
  ): string | undefined {
    if (!this.registry.has(iconName as meIcons) && this.meIconNameSet.includes(iconName as meIcons)) {
      console.error(`Иконка с именем ${iconName} не зарегистрирована!`);
      return undefined;
    } else if (!this.registry.has(iconName as meIcons)) {
      return this.colorIcon(this.parseIcon(iconName), color, selector);
    } else {
      const icon = this.registry.get(iconName as meIcons);
      return this.colorIcon(icon, color, selector);
    }
  }

  public colorIcon(
    iconComponent: any,
    color?: string | IconColorOptions[],
    selector?: string): string | undefined{
    let result;
    if(this.isSvgString(iconComponent))
    {
      result = iconComponent;
    }
    else
    {
      if (!this.registry.has(iconComponent as meIcons) && this.meIconNameSet.includes(iconComponent as meIcons))
      {
        console.error(`Иконка с именем ${iconComponent} не зарегистрирована!`);
        return undefined;
      } else
        if (!this.registry.has(iconComponent as meIcons))
        {
          return this.parseIcon(iconComponent);
        } else
          {
            result = this.registry.get(iconComponent as meIcons);
          }
    }

    if (!color)
    {
      return result
    }
    if (!selector && typeof color === 'string')
    {
      return result.replaceAll('currentColor', color);
    }

    if(selector && typeof color === 'string')
    {
      const svgDoc = this.parser.parseFromString(result, 'image/svg+xml');
      const selectors = svgDoc.querySelectorAll(selector);
      selectors.forEach((sel) => {
        sel.setAttribute('fill', color);
      });
      return this.serializer.serializeToString(svgDoc.documentElement);
    }

    if((Array.isArray(color)) || (Array.isArray(color)))
    {
      const svgDoc = this.parser.parseFromString(result, 'image/svg+xml');
      color.forEach((obj) =>{
        const selectors = svgDoc.querySelectorAll(obj.selector);
        selectors.forEach((sel) => {
          sel.setAttribute('fill', obj.color);
        });
      });
      return this.serializer.serializeToString(svgDoc.documentElement);
    }
    return undefined;
  }

  private isSvgString(str: string): boolean {
    if (!str) {
      return false;
    }
    const trimmed = str.trim();
    const svgRegex = /^<svg[\s\S]*<\/svg>$/i;
    return svgRegex.test(trimmed);
  }

  public getIcon(iconComponent: any, color?: string): string {
    if (!iconComponent.data) {
      console.warn(`Компонент ${iconComponent} не содержит svg строку!`);
    }

    this.registry.set(iconComponent.name, iconComponent.data);

    if (color) {
      return iconComponent.data?.replaceAll('currentColor', color) || '';
    } else {
      return iconComponent.data || '';
    }
  }

  public parseIcon(icon: string) {
    if (icon) {
      if (DX_ICONS.includes(icon))
        return ('<i class="dx-icon dx-icon-' + icon + '"></i>');
      if (icon.startsWith('<svg')) {
        return (icon);
      }
      if (icon.startsWith("data:image") || icon.startsWith("http"))
        return (`<img src="${icon}"/>`);
      if (REG_EXP_FOR_ICON_PATH.test(icon))
        return (`<img src="${icon}"/>`);
    }

    return icon;
  }

  public concatIcon(...icons: MeIcon[]) {
    let newsvg = icons.reduce((acc: any, item, index) => {
      if (index === 0) {
        let doc = this.parser.parseFromString(item.data, 'image/svg+xml');

        acc = doc.getElementsByTagName('svg')[0];
      } else {
        let nextIcon = this.parser.parseFromString(item.data, 'image/svg+xml');

        let path = nextIcon.getElementsByTagName('path')[0];

        if (!path) {
          path = nextIcon.getElementsByTagName('circle')[0];
        }

        path.setAttribute('fill', 'red');

        acc.append(path);
      }

      return acc;
    }, [])

    return this.serializer.serializeToString(newsvg);
  }

}
